REPLACE INTO `email_logs` (`id`, `communication_log_id`, `organization_id`, `user_id`, `template_name`, `to_email`, `subject`, `body`, `status`, `response_message`, `provider`, `sent_by`, `created_at`, `updated_at`, `attempts`, `sent_at`, `last_attempt_at`, `lead_id`) VALUES (1, NULL, 1, 2, NULL, 'de****@test.com', 'dfg Deepak Soni sdfsdf', '<p><img src=\"file:///C:/xampp/htdocs/crm/bc/Admin/dist/creative/assets/images/small/img-6.jpg\" alt=\"\"></p>\n<p><a>How to get creative in your work</a></p>\n<p>21 Nov 2021 sdf</p>\n<p>About</p>\n<p>Hi I\'m Anna Adame, It will be as simple as Occidental; in fact, it will be Occidental. To an English person, it will seem like simplified English, as a skeptical Cambridge friend of mine told me what Occidental is European languages are members of the same family.</p>\n<p>You always want to make sure that your fonts work well together and try to limit the number of fonts you use to three or less. Experiment and play around with the fonts that you already have in the software you&rsquo;re working with reputable font websites. This may be the most commonly encountered tip I received from the designers I spoke with. They highly encourage that you use different fonts in one design, but do not over-exaggerate and go overboard.</p>\n<p><img class=\"img-fluid\" src=\"../storage/tinymce/files/S8bAxPAwDCwQCXjJUwzGlCRCdH6Vk30JJyLXBjuJ.jpg\" alt=\"\" width=\"NaN\" height=\"NaN\"></p>\n<p>Designation :</p>\n<p>Lead Designer / Developer</p>\n<p>&nbsp;</p>\n<p>Website :</p>\n<p><a href=\"file:///C:/xampp/htdocs/crm/bc/Admin/dist/creative/pages-profile.html#\">www.velzon.com</a></p>', 'sent', 'sent', 'live.smtp.mailtrap.io', 2, '2026-02-12 06:36:20', '2026-02-12 11:50:27', 3, '2026-02-12 17:20:27', '2026-02-12 17:20:20', 16),
